from fractions import Fraction as Fr
from itertools import combinations
from math import prod
def brute(n):  # uniform over non-empty subsets of {1..n}
    subs=[c for k in range(1,n+1) for c in combinations(range(1,n+1),k)]
    return Fr(sum(prod(c)%2==0 for c in subs), len(subs))
for n in [2,4,6,8,10,12]:
    h=n//2; assert brute(n)==Fr(2**h*(2**h-1),2**n-1)
N,h=2026,1013
exact=Fr((2**N-1)-(2**h-1),2**N-1)  # complement of the 2^1013-1 all-odd non-empty subsets
opts={'A':Fr(2**h*(2**h-1),2**N),'B':Fr(2**h,2**N),'C':Fr(2**h*(2**h-1),2**N-1),'D':Fr(1,2**N-1)}
assert len(set(opts.values()))==4 and exact==Fr(2**h,2**h+1)
print([k for k,v in opts.items() if v==exact])  # ['C']
